export function createPresencePanel(publish) {
  let release = () => {};
  return {
    show(channel, bootstrapMode = "synchronous") {
      release();
      release = subscribeChannel(channel, bootstrapMode, publish);
    },
    close() {
      release();
      release = () => {};
    },
  };
}

export async function renderPresence(token, bootstrapMode) {
  const events = [];
